import multer from 'multer';
import { loadConfig } from '../config/env.ts';
import { AppError } from '../lib/errors.ts';

/**
 * Upload handling.
 *
 * Files are held in memory (bounded by the configured limits), the declared
 * MIME type is checked against an allow-list, and the *actual* file signature is
 * inspected before anything is stored — a request that claims to send a JPEG but
 * carries an executable or an HTML document is rejected. Storage keys are random
 * and generated by the server, so a caller can never choose where a file lands.
 */
const config = loadConfig();

export const ALLOWED_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/avif'] as const;
export const ALLOWED_EVIDENCE_TYPES = [...ALLOWED_IMAGE_TYPES, 'application/pdf'] as const;

export type DetectedFileType = 'jpeg' | 'png' | 'webp' | 'avif' | 'pdf' | 'gif' | 'unknown';

/** Sniffs the leading bytes of a file to determine its real container type. */
export function detectFileType(buffer: Buffer): DetectedFileType {
  if (buffer.length < 12) return 'unknown';
  if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) return 'jpeg';
  if (buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4e && buffer[3] === 0x47) return 'png';
  if (buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WEBP') return 'webp';
  if (buffer.subarray(0, 6).toString('ascii') === 'GIF87a' || buffer.subarray(0, 6).toString('ascii') === 'GIF89a') return 'gif';
  if (buffer.subarray(4, 8).toString('ascii') === 'ftyp') {
    const brand = buffer.subarray(8, 12).toString('ascii');
    if (brand.startsWith('avif') || brand.startsWith('avis') || brand.startsWith('mif1')) return 'avif';
  }
  if (buffer.subarray(0, 5).toString('ascii') === '%PDF-') return 'pdf';
  return 'unknown';
}

const TYPE_TO_MIME: Record<string, string> = {
  jpeg: 'image/jpeg',
  png: 'image/png',
  webp: 'image/webp',
  avif: 'image/avif',
  pdf: 'application/pdf',
};

export function extensionForDetectedType(type: DetectedFileType): string {
  switch (type) {
    case 'jpeg':
      return 'jpg';
    case 'png':
      return 'png';
    case 'webp':
      return 'webp';
    case 'avif':
      return 'avif';
    case 'pdf':
      return 'pdf';
    case 'gif':
      return 'gif';
    default:
      return 'bin';
  }
}

export interface ValidatedUpload {
  buffer: Buffer;
  mimeType: string;
  extension: string;
  originalName: string;
}

/**
 * Validates a single uploaded file. Returns the detected MIME type (not the
 * client-declared one) so the stored metadata cannot be spoofed.
 */
export function validateUploadedFile(
  file: { buffer: Buffer; mimetype: string; originalname: string; size: number },
  options: { kind: 'image' | 'evidence' },
): ValidatedUpload {
  const allowedMime = options.kind === 'image' ? ALLOWED_IMAGE_TYPES : ALLOWED_EVIDENCE_TYPES;
  const maxBytes = options.kind === 'image' ? config.media.limits.imageBytes : config.media.limits.evidenceBytes;

  if (file.size <= 0) throw AppError.validation('The uploaded file is empty');
  if (file.size > maxBytes) {
    throw AppError.validation(
      `${options.kind === 'image' ? 'Images' : 'Evidence files'} must be smaller than ${Math.round(maxBytes / (1024 * 1024))} MB`,
    );
  }
  if (!(allowedMime as readonly string[]).includes(file.mimetype)) {
    throw AppError.validation(
      options.kind === 'image'
        ? 'Only JPEG, PNG, WebP or AVIF images are accepted'
        : 'Only JPEG, PNG, WebP, AVIF images or PDF documents are accepted',
    );
  }

  const detected = detectFileType(file.buffer);
  if (detected === 'unknown') {
    throw AppError.validation('The file content could not be recognised as an allowed image or document type');
  }
  if (detected === 'gif') {
    throw AppError.validation('Animated GIF files are not accepted; convert the image to JPEG, PNG or WebP first');
  }
  if (options.kind === 'image' && detected === 'pdf') {
    throw AppError.validation('PDF files cannot be used as listing photographs');
  }

  return {
    buffer: file.buffer,
    mimeType: TYPE_TO_MIME[detected] ?? file.mimetype,
    extension: extensionForDetectedType(detected),
    originalName: file.originalname.slice(0, 160),
  };
}

function uploader(maxFileBytes: number, maxFiles: number) {
  return multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: maxFileBytes, files: maxFiles, fields: 20 },
    fileFilter: (_req, file, callback) => {
      if (!/^(image\/(jpeg|png|webp|avif)|application\/pdf)$/.test(file.mimetype)) {
        callback(AppError.validation(`The file type "${file.mimetype}" is not permitted for uploads`));
        return;
      }
      callback(null, true);
    },
  });
}

export const imageUpload = uploader(config.media.limits.imageBytes, config.media.limits.imagesPerListing);
export const evidenceUpload = uploader(config.media.limits.evidenceBytes, config.media.limits.evidenceFiles);
export const avatarUpload = uploader(config.media.limits.imageBytes, 1);
